import { useState, useEffect } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';

const useMarvelApi = (query) => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);

  const fetchData = async (loadMore = false) => {
    if (loadMore) {
      setOffset(data.length);
    } else {
      setOffset(0);
    }

    setLoading(true);
    try {
      const publicKey = process.env.REACT_APP_MARVEL_PUBLIC_KEY;
      const privateKey = process.env.REACT_APP_MARVEL_PRIVATE_KEY;
      const ts = new Date().getTime();
      const hash = CryptoJS.MD5(ts + privateKey + publicKey).toString();

      const baseURL = `https://gateway.marvel.com:443/v1/public/characters`;
      const response = await axios.get(baseURL, {
        params: {
          apikey: publicKey,
          ts,
          hash,
          nameStartsWith: query,
          offset: loadMore ? data.length : 0, // Update offset if loading more
          limit: 20,
        },
      });

      if (loadMore) {
        setData(prev => [...prev, ...response.data.data.results]);
      } else {
        setData(response.data.data.results);
      }
      setHasMore(data.length < response.data.data.total);
    } catch (error) {
      setError(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [query]);

  return { data, loading, error, hasMore, fetchData };
};

export default useMarvelApi;
